from itertools import combinations

def _kernel_2035(nums):
    n = len(nums) >> 1
    total = sum(nums)
    left = nums[:n]
    right = nums[n:]
    comb = combinations
    best = 1 << 62
    for k in range(n + 1):
        lk = sorted(map(sum, comb(left, k)))
        rk = sorted(map(sum, comb(right, n - k)))
        q = len(rk) - 1
        last = len(rk) - 1
        for sL in lk:
            T = total - 2 * sL
            while q >= 0 and 2 * rk[q] > T:
                q -= 1
            if q >= 0:
                d = T - 2 * rk[q]
                if d < 0:
                    d = -d
                if d < best:
                    best = d
                    if best == 0:
                        return 0
            if q < last:
                d = T - 2 * rk[q + 1]
                if d < 0:
                    d = -d
                if d < best:
                    best = d
                    if best == 0:
                        return 0
    return best

class Solution:
    def minimumDifference(self, nums):
        return _kernel_2035(nums)

